                revert DeltaMustBeNonZero(delta.depositor);
            }

            // Add to the total delta
            totalDelta += delta.value;
        }

        // Make sure everything netted to zero
        if (totalDelta != 0) {
            revert MustNetToZero(totalDelta);
        }
    }
}

